color:#ef4444;box-shadow:0 0 0 3px rgba(239,68,68,.10)}.annotation-settings-page .as-input:disabled,.annotation-settings-page .as-select:disabled{opacity:.52;background:color-mix(in srgb,var(--panel2) 82%,transparent)}.annotation-settings-page .as-readonly{display:flex;align-items:center;color:var(--muted);background:var(--panel2)}.annotation-settings-page textarea.as-input{min-height:72px;resize:vertical}.annotation-settings-page .as-field>.as-switch{width:100%;min-height:40px;margin:0;display:flex;align-items:center;gap:11px;color:var(--text);cursor:pointer}.annotation-settings-page .as-switch input{position:absolute;width:1px;height:1px;opacity:0;pointer-events:none}.annotation-settings-page .as-switch i{position:relative;display:block;width:46px;height:26px;border-radius:999px;background:#cbd5e1;flex:0 0 46px;overflow:hidden;transition:background .16s ease,box-shadow .16s ease}.annotation-settings-page .as-switch i:after{content:'';position:absolute;left:4px;top:4px;width:18px;height:18px;border-radius:50%;background:#fff;box-shadow:0 2px 7px rgba(0,0,0,.18);transition:transform .16s ease}.annotation-settings-page .as-switch input:focus-visible+i{box-shadow:0 0 0 3px rgba(59,130,246,.16)}.annotation-settings-page .as-switch input:checked+i{background:linear-gradient(135deg,var(--brand),var(--brand2))}.annotation-settings-page .as-switch input:checked+i:after{transform:translateX(20px)}.annotation-settings-page .as-switch input:disabled+i,.annotation-settings-page .as-switch input:disabled~span{opacity:.52}.annotation-settings-page .as-switch span{min-width:0;font-size:13px;font-weight:700;line-height:1.45}.annotation-settings-page .as-color-control{position:relative}.annotation-settings-page .as-color-swatch{position:absolute;left:12px;top:50%;transform:translateY(-50%);width:17px;height:17px;border:1px solid rgba(15,23,42,.18);border-radius:5px;pointer-events:none;transition:background .16s ease}.annotation-settings-page .as-color-control .as-select{padding-left:40px}.annotation-settings-page .as-flash .as-input,.annotation-settings-page .as-flash .as-select,.annotation-settings-page .as-flash .as-switch{animation:asFieldFlash .65s ease}
