        public static string BuildComponentScript()
        {
            string script = BuildRawComponentScript();
            script = script.Replace("step=\"0.1\"", "step=\"0.01\"");
            script = script.Replace("step=\"0.05\"", "step=\"0.01\"");
            script = script.Replace("step=\"0.001\"", "step=\"0.01\"");
            script = script.Replace(
                "AnnotationSettingsPage.prototype.colorSelect=function(path,value){var h='<div class=\"as-color-control\"><span class=\"as-color-swatch\"></span><select class=\"as-select\" data-color-select data-field=\"'+path+'\" data-type=\"int\">';this.colors.forEach(function(c){h+='<option value=\"'+c.index+'\" data-color=\"'+esc(c.cssColor)+'\" '+(Number(c.index)===Number(value)?'selected':'')+'>'+esc(c.name)+' · '+c.index+'</option>';});return h+'</select></div>';};",
                "AnnotationSettingsPage.prototype.colorSelect=function(path,value){var c=null;for(var i=0;i<this.colors.length;i++){if(Number(this.colors[i].index)===Number(value)){c=this.colors[i];break;}}c=c||{index:value,name:'ACI '+value,cssColor:'#94a3b8',rgb:''};return '<div class=\"as-color-control\"><button type=\"button\" class=\"as-color-picker\" data-color-picker data-field=\"'+path+'\" data-index=\"'+c.index+'\"><span class=\"as-color-swatch\" style=\"background:'+esc(c.cssColor)+'\"></span><span class=\"as-color-copy\"><strong>'+esc(c.name)+'</strong><small>'+esc(c.rgb||('ACI '+c.index+' · '+c.cssColor))+'</small></span><span class=\"as-color-arrow\">›</span></button></div>';};");
            script = script.Replace("this.$$('[data-field]').forEach", "this.$$('[data-field]:not([data-color-picker])').forEach");
            script = script.Replace(
                "document.addEventListener('click',function(ev){var s=self.$('.as-reset-split');",
                "document.addEventListener('click',function(ev){var color=ev.target.closest('[data-color-picker]');if(color&&self.root.contains(color)){ev.preventDefault();self.post('openAnnotationColorPicker',JSON.stringify({path:color.getAttribute('data-field'),index:Number(color.getAttribute('data-index')||7)}));return;}var s=self.$('.as-reset-split');");
            script = script.Replace(
                "w.CDBoxAnnotationSettingsPage=api;",
                "w.CDBoxAnnotationColorSelected=function(p){instances.forEach(function(i){if(!p||!p.path||!i.loaded)return;set(i.current,p.path,Number(p.index));i.render(false);});};w.CDBoxAnnotationSettingsPage=api;");
            return script;
        }

        private static string BuildRawComponentScript()
        {
            return Encoding.UTF8.GetString(Convert.FromBase64String(""));
        }


        private static string BuildStandaloneVariables()
        {
            return @"
:root{--bg:#f5f7fb;--panel:#fff;--panel2:#f8fafc;--muted:#64748b;--text:#162033;--line:#dce8f6;--brand:#3b82f6;--brand2:#7c3aed;--shadow:0 20px 45px rgba(30,41,59,.08);--shadow2:0 10px 24px rgba(30,41,59,.08)}
body[data-theme='fresh']{--bg:#f3f7ff;--panel:#fff;--panel2:#eef4ff;--muted:#65758f;--text:#172033;--line:#dbe7ff;--brand:#2563eb;--brand2:#9333ea}body[data-theme='dark']{--bg:#0f172a;--panel:#172033;--panel2:#111827;--muted:#94a3b8;--text:#e5e7eb;--line:#26364d;--brand:#60a5fa;--brand2:#a78bfa;--shadow:0 20px 45px rgba(0,0,0,.28);--shadow2:0 10px 24px rgba(0,0,0,.24)}
*{box-sizing:border-box}html,body{height:100%;margin:0;background:var(--bg);color:var(--text);font-family:'Microsoft YaHei UI','Segoe UI',sans-serif;overflow:hidden}
";
        }

        private static string NormalizeSection(string section)
        {
            string value = (section ?? string.Empty).Trim().ToLowerInvariant();
            if (value == "pipe" || value == "pipe-length" || value == "pipelength") return "pipeLength";
            if (value == "node") return "node";
            return "surface";
        }

        private static string Html(string value)
        {
            if (string.IsNullOrEmpty(value)) return string.Empty;
            return value.Replace("&", "&amp;").Replace("<", "&lt;").Replace(">", "&gt;").Replace("\"", "&quot;").Replace("'", "&#39;");
        }

        private static string HtmlAttr(string value)
        {
            return Html(value).Replace("\r", string.Empty).Replace("\n", " ");
        }

        private static string ToJsString(string value)
        {
            if (value == null) return "''";
            return "'" + value.Replace("\\", "\\\\").Replace("'", "\\'").Replace("\r", "\\r").Replace("\n", "\\n") + "'";
        }
    }
}
